def main():
    import numpy as np
    import sympy as sp
    from scipy.integrate import quad
    from scipy.special import polygamma
    root=Path(__file__).resolve().parents[1];checks=[]
    def check(label,condition):
        checks.append(bool(condition));print(f"[{'PASS' if condition else 'FAIL'}] {label}")
    b=json.loads((root/'outputs/all_late_complete_2026_10_17/landing/PROOF_INPUT_BINDING.json').read_text())
    check('186 original pins,12 current parents and9 mapping manifests match',len(b['pins'])==186 and len(b['current_parents'])==12 and len(b['provenance_manifests'])==9 and all((root/r['path']).is_file() and hashlib.sha256((root/r['path']).read_bytes()).hexdigest()==r['sha256'] for r in b['pins']+b['current_parents']+b['provenance_manifests']))

    # Exact algebra, with the physical Weyl square root and its derivative.
    delta,lam,j=sp.symbols('delta lam j',positive=True,real=True)
    mj=delta/(2*j**2)-sp.I*sp.sqrt(1-delta**2/(4*j**2))/j
    p2=delta**2-lam**2/3;q3=p2*(delta-3*j*lam*mj)-8*lam**2*delta/3
    rewritten=(delta+sp.I*lam)**3-3*j*lam*p2*(mj+sp.I/j)
    product_derivative=2*delta*(delta-3*j*lam*mj)+p2*(1-3*j*lam*sp.diff(mj,delta))-8*lam**2/3
    check('q3 cubic correction identity and physical derivative retain complex Weyl load',sp.expand(q3-rewritten)==0 and sp.simplify(sp.diff(q3,delta)-product_derivative)==0)
    q,k,qp=sp.symbols('q k qp',real=True)
    N=sp.sin(q)*sp.sin(k)/sp.sin((q+k)/2)
    derivative=sp.diff(N,q)*qp+sp.diff(N,k)
    logarithmic=N*(sp.cot(q)*qp+sp.cot(k)-sp.cot((q+k)/2)*(qp+1)/2)
    # Normalize cotangents to explicit ratios before common-denominator
    # cancellation. trigsimp alone can retain an unsimplified double-angle zero.
    ratios={sp.cot(q):sp.cos(q)/sp.sin(q),sp.cot(k):sp.cos(k)/sp.sin(k),sp.cot((q+k)/2):sp.cos((q+k)/2)/sp.sin((q+k)/2)}
    exact_residual=sp.cancel((derivative-logarithmic).subs(ratios))
    missing_half_angle=N*(sp.cot(q)*qp+sp.cot(k))
    mutant_residual=sp.cancel((derivative-missing_half_angle).subs(ratios))
    check('physical numerator logarithmic derivative including half-angle factor; omitted-factor mutant detected',exact_residual==0 and mutant_residual!=0)
    # Quotient/phase derivative without fitting either phase or denominator.
    x=sp.symbols('x',real=True);nf=sp.Function('N')(x);df=sp.Function('D')(x);phase=sp.Function('phi')(x)
    F=sp.exp(sp.I*phase)*nf/df
    prescribed=sp.exp(sp.I*phase)*((sp.I*sp.diff(phase,x)*nf+sp.diff(nf,x))/df-nf*sp.diff(df,x)/df**2)
    check('full coefficient phase/numerator/denominator derivative identity',sp.simplify(sp.diff(F,x)-prescribed)==0)

    # Finite hard-edge IBP witness; the coefficient is nonzero at both ends.
    a=.4;c=1.1;t=1.3;g=.7;n=0
    f=lambda z:1+.2*z+.1j*z*z
    fp=lambda z:.2+.2j*z
    psi=lambda z:-n*z+2*t*g*np.cos(z)
    psip=lambda z:-n-2*t*g*np.sin(z)
    psipp=lambda z:-2*t*g*np.cos(z)
    integrate=lambda fun:quad(lambda z:fun(z).real,a,c,epsabs=1e-11)[0]+1j*quad(lambda z:fun(z).imag,a,c,epsabs=1e-11)[0]
    direct=integrate(lambda z:f(z)*np.exp(1j*psi(z)))
    edge=f(c)*np.exp(1j*psi(c))/(1j*psip(c))-f(a)*np.exp(1j*psi(a))/(1j*psip(a))
    remainder=integrate(lambda z:(fp(z)/(1j*psip(z))-f(z)*psipp(z)/(1j*psip(z)**2))*np.exp(1j*psi(z)))
    check('hard-edge IBP equals direct finite integral with both endpoints',abs(direct-(edge-remainder))<1e-10)
    check('omitting hard edges is detected',abs(edge)>.1 and abs(direct+remainder)>.1)

    # Infinite sums evaluated by trigamma and bracketed by finite monotone tails.
    sumok=True;zero_mutant=False
    for z in (.2,1.,3.,10.):
        Ncut=10000;terms=1/(z+np.arange(Ncut))**2;partial=terms.sum();s0=float(polygamma(1,z));s1=float(polygamma(1,z+1))
        sumok &= partial+1/(z+Ncut)<=s0+1e-11 and s0<=partial+1/(z+Ncut-1)+1e-11
        sumok &= s0<=z**-2+1/z+1e-11 and s1<=1/z+1e-11 and abs(s0-s1-z**-2)<1e-10
        zero_mutant |= s0>1/z+1e-3
    check('integer halfline sums distinguish incoming n>=0 from excluded outgoing n>=1',sumok)
    check('using outgoing bound for incoming and dropping m=0 is detected',zero_mutant)

    # Dimensionless abstract constants, deliberately not a physical parameter point.
    # Six sufficient thresholds allocate four decays, and keep r positive.
    allocation=True;normalization=True
    for speed,B,H,rate,p,gap in [(1.,.7,.4,.8,.9,.2),(.3,2.,1.,.2,.4,.05),(2.,.1,.02,3.,.99,40.)]:
        onset=max(1/speed,2/rate*max(0,np.log(36/gap)),4*H/gap,16*B*B/(np.pi*speed*gap*gap),B*B/(np.pi*speed*p),2*B*B/(np.pi*speed*np.sqrt(p)*gap))
        for factor in (1.,2.,10.):
            time=factor*onset;z=speed*time;left2=B*B/(2*np.pi*z);r=np.sqrt(p-left2)
            decays=[9*np.exp(-rate*time/2),H/time,B/np.sqrt(2*np.pi)*np.sqrt(z**-2+z**-1),np.sqrt(p)-r]
            allocation &= left2<=p/2+1e-12 and r>0 and max(decays)<=gap/4+1e-10 and sum(decays)<=gap+1e-10
            normalization &= abs((1-r)-(1-np.sqrt(p))-(np.sqrt(p)-r))<1e-12
    check('generic six-threshold onset allocates four decreasing allowances and ensures r>0',allocation)
    check('raw normalization pays fixed mass deficit once plus decaying halfline correction',normalization)
    check('fixed scalar mass deficit need not vanish at late times',1-np.sqrt(.9)>0)
    print('Scope: symbolic scalar identities, finite hard-edge integral and generic sum/onset controls. No numerical apparatus onset or finite-receiver all-future promise. Full conditional proof and supplied physical premises remain controlling; historical53f571b6 is not adopted.')
    print(f'TOTAL: PASS={sum(checks)} FAIL={len(checks)-sum(checks)}')
    return 0 if all(checks) else 1


if __name__ == '__main__':
    raise SystemExit(main())
